 const pointer=async element=>{await iframe.evaluate(e=>e.scrollIntoView({block:'start',behavior:'instant'}));await element.evaluate(e=>e.scrollIntoView({block:'center',behavior:'instant'}));await frame.waitForFunction(e=>{const r=e.getBoundingClientRect(),s=getComputedStyle(e),hit=document.elementFromPoint(r.x+r.width/2,r.y+r.height/2);return r.width>0&&r.height>0&&Number(s.opacity)>0&&s.visibility==='visible'&&!e.disabled&&(hit===e||e.contains(hit));},{timeout:15000},element);await element.click();};
 const click=async label=>pointer(await waitForMailButton(frame,label));
