 await click({parts:[source.subject]});await frame.waitForFunction(subject=>[...document.querySelectorAll('section h2')].some(e=>e.textContent===subject),{},source.subject);
 const actorPath='/api/secureshop/email/auto-reply/'+source.thread_id,gradePath='/api/secureshop/email/reply-assessment';let cdp,error,firstGrade,recovered,privateHeaders,lost=false;
